'use client';

import React, { useState } from 'react';
import { Card, Button } from '@/components/ui/base';
import { Plus, TrendingUp, TrendingDown, Info } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { AddTransactionModal } from '@/components/ui/add-transaction-modal';
import { useTransactions } from '@/lib/transaction-context';

export default function DashboardPage() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { transactions, stats } = useTransactions();

  // Process data for charts
  const chartData = React.useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      return d.toISOString().split('T')[0];
    });

    return last7Days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const income = dayTransactions.filter(t => t.type === 'Income').reduce((acc, t) => acc + t.amount, 0);
      const expense = dayTransactions.filter(t => t.type === 'Expense').reduce((acc, t) => acc + t.amount, 0);
      return {
        name: new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        income,
        expense
      };
    });
  }, [transactions]);

  const pieData = React.useMemo(() => {
    const expenses = transactions.filter(t => t.type === 'Expense');
    const categories = Array.from(new Set(expenses.map(t => t.category)));
    const colors = ['#f97316', '#10b981', '#0f172a', '#ef4444', '#8b5cf6', '#f59e0b'];
    
    return categories.map((category, index) => ({
      name: category,
      value: expenses.filter(t => t.category === category).reduce((acc, t) => acc + t.amount, 0),
      color: colors[index % colors.length]
    })).sort((a, b) => b.value - a.value).slice(0, 5);
  }, [transactions]);

  const incomeCount = transactions.filter(t => t.type === 'Income').length;
  const expenseCount = transactions.filter(t => t.type === 'Expense').length;

  return (
    <div className="space-y-8">
      <AddTransactionModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      
      {/* Header Section */}
      <div className="bg-[#111827] text-white p-8 rounded-2xl shadow-lg -mt-4">
        <div className="flex justify-between items-start mb-8">
          <div>
            <h1 className="text-3xl font-bold mb-2">Welcome back, TechWithEmma</h1>
            <p className="text-gray-400">This is your overview report for the selected period</p>
          </div>
          <div className="flex gap-4 items-center">
            <select className="bg-[#1f2937] border-none text-white rounded-md px-4 py-2 text-sm focus:ring-2 focus:ring-green-500">
              <option>Last 30 Days</option>
              <option>Last 7 Days</option>
              <option>This Month</option>
            </select>
            <Button variant="primary" className="gap-2" onClick={() => setIsModalOpen(true)}>
              <Plus size={18} /> Add Transaction
            </Button>
          </div>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-[#1f2937] p-6 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-blue-400 text-sm font-medium">Available Balance</h3>
            </div>
            <p className="text-3xl font-bold mb-2">${stats.netProfit.toLocaleString('en-US', { minimumFractionDigits: 2 })}</p>
            <p className="text-green-400 text-xs flex items-center gap-1">
              <TrendingUp size={12} /> +38.8% <span className="text-gray-500">for Past 30 Days</span>
            </p>
          </div>

          <div className="bg-[#1f2937] p-6 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-gray-400 text-sm font-medium">Total Income</h3>
            </div>
            <p className="text-3xl font-bold mb-2">${stats.totalIncome.toLocaleString('en-US', { minimumFractionDigits: 2 })}</p>
            <p className="text-green-400 text-xs flex items-center gap-1">
              <TrendingUp size={12} /> +25.0% <span className="text-gray-500">for Past 30 Days</span>
            </p>
          </div>

          <div className="bg-[#1f2937] p-6 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-gray-400 text-sm font-medium">Total Expenses</h3>
            </div>
            <p className="text-3xl font-bold mb-2">-${stats.totalExpense.toLocaleString('en-US', { minimumFractionDigits: 2 })}</p>
            <p className="text-red-400 text-xs flex items-center gap-1">
              <TrendingDown size={12} /> -21.6% <span className="text-gray-500">for Past 30 Days</span>
            </p>
          </div>

          <div className="bg-[#1f2937] p-6 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-gray-400 text-sm font-medium">Savings Rate</h3>
            </div>
            <p className="text-3xl font-bold mb-2">
              {stats.totalIncome > 0 ? ((stats.netProfit / stats.totalIncome) * 100).toFixed(1) : 0}%
            </p>
            <p className="text-red-400 text-xs flex items-center gap-1">
              <TrendingDown size={12} /> High Spend <span className="text-gray-500">• {stats.totalIncome > 0 ? ((stats.totalExpense / stats.totalIncome) * 100).toFixed(0) : 0}% spent</span>
            </p>
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Transaction Overview Chart */}
        <Card className="lg:col-span-2 p-6">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold text-gray-900">Transaction Overview</h3>
              <p className="text-sm text-gray-500">Showing total transactions for Past 7 Days</p>
            </div>
            <div className="flex gap-6">
              <div className="text-right">
                <p className="text-xs text-gray-500">No of Income</p>
                <p className="font-bold text-green-500 flex items-center justify-end gap-1"><TrendingUp size={14}/> {incomeCount}</p>
              </div>
              <div className="text-right">
                <p className="text-xs text-gray-500">No of Expenses</p>
                <p className="font-bold text-red-500 flex items-center justify-end gap-1"><TrendingDown size={14}/> {expenseCount}</p>
              </div>
            </div>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{fill: '#f9fafb'}}
                />
                <Bar dataKey="income" fill="#4ade80" radius={[4, 4, 0, 0]} maxBarSize={40} />
                <Bar dataKey="expense" fill="#f87171" radius={[4, 4, 0, 0]} maxBarSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>

        {/* Expenses Breakdown Chart */}
        <Card className="p-6">
          <div className="mb-6">
            <h3 className="text-lg font-bold text-gray-900">Expenses Breakdown</h3>
            <p className="text-sm text-gray-500">Total expenses by category</p>
          </div>
          <div className="h-[250px] w-full relative flex items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <p className="text-2xl font-bold text-gray-900">${stats.totalExpense.toLocaleString()}</p>
              <p className="text-xs text-gray-500">Total Spent</p>
            </div>
          </div>
          <div className="mt-4 space-y-3">
            {pieData.map((item) => (
              <div key={item.name} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                  <span className="text-gray-600">{item.name}</span>
                </div>
                <div className="flex items-center gap-4">
                  <span className="font-medium text-gray-900">${item.value.toLocaleString()}.00</span>
                  <span className="text-gray-400 text-xs">({stats.totalExpense > 0 ? Math.round(item.value / stats.totalExpense * 100) : 0}%)</span>
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
}
